                'attempts' => 1,
                'last_error' => 'Render failed: '.$e->getMessage(),
                'sent_at' => now(),
            ]);
            throw $e;
        }

        // SEND FAILURES ARE ALSO CAUGHT AND LOGGED
        $log = AuditEmailLog::create([
            'audit_request_id' => $auditRequest?->id,
            'mailable' => $mailableName,
            'recipient' => $recipient,
            'subject' => $subject,
            'body' => $body,
            'status' => AuditEmailLog::STATUS_PENDING,
            'attempts' => 1,
            'sent_at' => now(),
        ]);

        try {
            Mail::to($recipient)->send($mailable);
            $log->update(['status' => AuditEmailLog::STATUS_SENT]);
        } catch (Throwable $e) {
            $log->update(['status' => AuditEmailLog::STATUS_FAILED, 'last_error' => $e->getMessage()]);
            throw $e;
        }

        return $log;
    }
}
```

**Key Points:**
- Catches and logs render failures (Blade template compilation, missing views)
- Catches and logs send failures (queue backend, transport errors)
- Both exceptions are **rethrown** after logging
- Stores full rendered HTML body in the database

